where dataTable.delete_flag = '0'

	AND dataTable.tenant_id = #{tenantId}


	AND dataTable.device_code = #{deviceCode}


	AND dataTable.suppress_begin_time <= #{suppressBeginTime}
	AND dataTable.suppress_end_time >= #{suppressBeginTime}

mapper.update:
update vm_alarm_suppress_config
	set suppress_begin_time = #{suppressBeginTime},
		suppress_end_time = #{suppressEndTime},
		suppress_continuous_time = #{suppressContinuousTime},
		suppress_interval_type = #{suppressIntervalType},
	    update_by = #{updateBy},
	    update_time = #{updateTime}
WHERE tenant_id = #{tenantId}
  and device_code = #{deviceCode}
  and delete_flag = '0'

mapper.delete:
		DELETE from vm_alarm_suppress_config
        WHERE tenant_id = #{tenantId}
		  and device_code = #{deviceCode}
		  and delete_flag = '0'
